```
import string

# 自定义字符集
c_charset = string.ascii_uppercase + string.ascii_lowercase + string.digits + '()'

# 凯撒逆变换（字母前移2位）
def unrend(s):
    def decode_ch(ch):
        if ch.islower():
            return chr((ord(ch) - 97 - 2) % 26 + 97)
        elif ch.isupper():
            return chr((ord(ch) - 65 - 2) % 26 + 65)
        else:
            return ch
    return ''.join(decode_ch(c) for c in s)

# 自定义 Base64 解码
def custom_b64_decode(s):
    # 移除填充点（如果有）
    s = s.rstrip('.')
    binary_str = ''
    for ch in s:
        idx = c_charset.index(ch)
        binary_str += '{:06b}'.format(idx)
    # 按8位分割还原字节
    bytes_list = []
    for i in range(0, len(binary_str), 8):
        byte_chunk = binary_str[i:i+8]
        if len(byte_chunk) == 8:
            bytes_list.append(int(byte_chunk, 2))
    return bytes(bytes_list)

# 目标密文
flag_encoded = 'BozjB3vlZ3ThBn9bZ2jhOH93ZaH9'

# 第一步：凯撒逆向
b64_str = unrend(flag_encoded)
print(f'凯撒逆向后的 Base64 串：{b64_str}')

# 第二步：自定义 Base64 解码
original_bytes = custom_b64_decode(b64_str)
flag = original_bytes.decode('ascii')
print(f'解码结果：{flag}')
